	// `excludedFromCommit`) is partially staged. Working tree only; in-memory and
	// pruned/reset alongside `excludedFromCommit`.
	stagingLineExclusions: SvelteSet<string>;
	collapsedFiles: SvelteSet<string>;
	viewMode: ViewMode;
