	// GitHub remote.
	async createIssueOnGithub(): Promise<void> {
		const host = githubHostRepo();
		if (!host) return;
		await window.api.shell.openExternal(`https://github.com/${host.owner}/${host.repo}/issues/new`);
	},

	// Open a file with the OS default program for its type.
