on\\\": \\\"Two tweaks to the inline PR comment thread: tightened the vertical whitespace around the reply box, and added a \\\\\\\"View on GitHub\\\\\\\" item to each comment's overflow menu.\\\",\\n  \\\"harness\\\": \\\"claude-code\\\",\\n  \\\"branch\\\": \\\"claude/modest-brahmagupta-d2mvd\\\",\\n  \\\"baseRef\\\": \\\"8f02e55fe4ea353fff08a83a7f0fb36f2417846c\\\",\\n  \\\"createdAt\\\": 1780668125104,\\n  \\\"updatedAt\\\": 1780668125104,\\n  \\\"fileCount\\\": 1,\\n  \\\"additions\\\": 27,\\n  \\\"deletions\\\": 9,\\n  \\\"stepCount\\\": 2,\\n  \\\"steps\\\": [\\n    {\\n      \\\"id\\\": \\\"step-1\\\",\\n      \\\"title\\\": \\\"Tighten reply-box spacing\\\",\\n      \\\"body\\\": \\\"The reply box had ~16px of dead space above it and ~18px below before the Resolve bar. Verified the exact gaps with an isolated repro (the gap is pure CSS margin, no hidden markdown element). Cut the reply box's top margin to **4px** and the thread-actions bar to **6px** margin + **6px** padding, keeping the divider rule.\\\",\\n      \\\"paths\\\": [\\n        \\\"apps/desktop/src/renderer/src/lib/components/CommentAnnotation.svelte\\\"\\n      ],\\n      \\\"callouts\\\": [\\n        {\\n          \\\"id\\\": \\\"step-1-c1\\\",\\n          \\\"file\\\": \\\"apps/desktop/src/renderer/src/lib/components/CommentAnnotation.svelte\\\",\\n          \\\"startLine\\\": 322,\\n          \\\"endLine\\\": 322,\\n          \\\"side\\\": \\\"new\\\",\\n          \\\"body\\\": \\\"Gap above the reply box: was 10px (total 16px with .text margin-bottom), now 4px.\\\"\\n        },\\n        {\\n          \\\"id\\\": \\\"step-1-c2\\\",\\n          \\\"file\\\": \\\"apps/desktop/src/renderer/src/lib/components/CommentAnnotation.svelte\\\",\\n          \\\"startLine\\\": 355,\\n          \\\"endLine\\\": 356,\\n          \\\"side\\\": \\\"new\\\",\\n          \\\"body\\\": \\\"Gap below the reply box, before Resolve: was 10px margin + 8px padding, now 6px + 6px.\\\"\\n        }\\n      ]\\n    },\\n    {\\n      \\\"id\\\": \\\"step-2\\\",\\n      \\\"title\\\": \\\"Add \\\\\\\"View on GitHub\\\\\\\" to the comment menu\\\",\\n      \\\"body\\\": \\\"The overflow (•••) menu previously only rendered when the comment was deletable. Now it always renders so every comment exposes **View on GitHub**, which opens the comment's API permalink (`comment.url`) via `window.api.shell.openExternal`. Delete stays, moved behind a separator when the viewer can delete.\\\",\\n      \\\"paths\\\": [\\n        \\\"apps/desktop/src/renderer/src/lib/components/CommentAnnotation.svelte\\\"\\n      ],\\n      \\\"callouts\\\": [\\n        {\\n          \\\"id\\\": \\\"step-2-c1\\\",\\n          \\\"file\\\": \\\"apps/desktop/src/renderer/src/lib/components/CommentAnnotation.svelte\\\",\\n          \\\"startLine\\\": 117,\\n          \\\"endLine\\\": 122,\\n          \\\"side\\\": \\\"new\\\",\\n          \\\"body\\\": \\\"Opens the comment permalink in the browser; no-ops if url is empty (e.g. a just-created comment not yet refetched).\\\"\\n        },\\n        {\\n          \\\"id\\\": \\\"step-2-c2\\\",\\n          \\\"file\\\": \\\"apps/desktop/src/renderer/src/lib/components/CommentAnnotation.svelte\\\",\\n          \\\"startLine\\\": 192,\\n          \\\"endLine\\\": 197,\\n          \\\"side\\\": \\\"new\\\",\\n          \\\"body\\\": \\\"New menu item, gated on c.url so it only shows when there's a permalink to open.\\\"\\n        }\\n      ]\\n    }\\n  ],\\n  \\\"files\\\": [\\n    {\\n      \\\"path\\\": \\\"apps/desktop/src/renderer/src/lib/components/CommentAnnotation.svelte\\\",\\n      \\\"status\\\": \\\"modified\\\",\\n      \\\"additions\\\": 27,\\n      \\\"deletions\\\": 9,\\n      \\\"isBinary\\\": false,\\n      \\\"patch\\\": \\\"diff --git a/apps/desktop/src/renderer/src/lib/components/CommentAnnotation.svelte b/apps/desktop/src/renderer/src/lib/components/CommentAnnotation.svelte\\\\nindex bdf683fd..09f71108 100644\\\\n--- a/apps/desktop/src/renderer/src