x;\n\t\talign-items: center;\n\t\tgap: 10px;\n\t\twidth: 100%;\n\t\tmargin-top: 4px;\n\t}\n\t/* Expanded reply editor — same composer as a new comment, with a little space\n     above to set it off from the comment it replies to. */\n\t.reply-composer {\n\t\tmargin-top: 8px;\n\t}\n\t.reply-avatar {\n\t\tborder-radius: 999px;\n\t\tflex-shrink: 0;\n\t}\n\t.reply-box {\n\t\tflex: 1;\n\t\tmin-width: 0;\n\t\tpadding: 6px 10px;\n\t\tfont: inherit;\n\t\tfont-size: 13px;\n\t\tcolor: var(--color-foreground);\n\t\tbackground: var(--color-background);\n\t\tborder: 1px solid var(--color-border);\n\t\tborder-radius: 6px;\n\t\toutline: none;\n\t\tcursor: text;\n\t}\n\t.reply-box::placeholder {\n\t\tcolor: var(--color-muted-foreground);\n\t}\n\t.reply-box:focus {\n\t\tborder-color: var(--color-ring);\n\t}\n\t.reply-box:disabled {\n\t\topacity: 0.6;\n\t}\n\t/* Sits below the last comment, separated by a rule, so the resolve toggle\n     reads as a thread-level action rather than part of that comment. Kept\n     outside `.comment` so it stays full-opacity even when the thread is\n     resolved (and its comments are dimmed). */\n\t.thread-actions {\n\t\tdisplay: flex;\n\t\tmargin-top: 6px;\n\t\tpadding-top: 6px;\n\t\tborder-top: 1px solid var(--color-border);\n\t}\n\t.resolved-tag {\n\t\tdisplay: inline-flex;\n\t\talign-items: center;\n\t\tgap: 3px;\n\t\tfont-size: 10px;\n\t\tfont-weight: 600;\n\t\tline-height: 1;\n\t\tpadding: 2px 6px;\n\t\tborder-radius: 999px;\n\t\t/* Use the defined `--color-success` token (a full hsl() value); color-mix\n       gives it a translucent fill — same approach used in DiffFileSection. */\n\t\tbackground: color-mix(in srgb, var(--color-success) 15%, transparent);\n\t\tcolor: var(--color-success);\n\t}\n\t.avatar {\n\t\tborder-radius: 999px;\n\t\tmargin-top: 2px;\n\t}\n\t.body header {\n\t\tdisplay: flex;\n\t\tgap: 8px;\n\t\talign-items: center;\n\t\tfont-size: 12px;\n\t}\n\t.author {\n\t\tfont-weight: 600;\n\t}\n\t.time {\n\t\tcolor: hsl(var(--muted-foreground));\n\t\tfont-size: 11px;\n\t}\n\t.text {\n\t\tfont-size: 13px;\n\t\tline-height: 1.45;\n\t\tmargin: 4px 0 6px;\n\t\twhite-space: pre-wrap;\n\t\tword-break: break-word;\n\t}\n\t.composer {\n\t\tdisplay: flex;\n\t\tflex-direction: column;\n\t\tgap: 6px;\n\t}\n\t.composer-header {\n\t\tdisplay: flex;\n\t\tgap: 6px;\n\t\talign-items: center;\n\t\tfont-size: 12px;\n\t\tcolor: hsl(var(--muted-foreground));\n\t}\n\t.composer-footer {\n\t\tdisplay: flex;\n\t\tjustify-content: flex-end;\n\t\talign-items: center;\n\t}\n\t.actions {\n\t\tdisplay: flex;\n\t\tgap: 4px;\n\t}\n\t.kbd {\n\t\tfont-family: inherit;\n\t\tfont-size: 10px;\n\t\tline-height: 1;\n\t\tpadding: 2px 4px;\n\t\tborder-radius: 4px;\n\t\tbackground: hsl(var(--foreground) / 0.08);\n\t\topacity: 0.7;\n\t}\n</style>\n",
